head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL25720";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25720.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comNm"] ?? ""); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

// [A] 초기 목록 미해결 — jldfil25720: 진입 키 advcecominfo 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_advceComApplList_oncellclick
 * @description grd_advceComApplList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_advceComApplList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_advceComApplList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_advceComApplList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "selChk") { scwin.loadForm(r["seq"], r["advceComIsurCd"], r["comNm"], r["advceComApplTpCd"], r["applReqDd"], r["contrtDd"], r["releasDd"], r["advceComProcsStatNm"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_advceComApplList.oncellclick' });
    }
};

/**
 * @method
 * @name rd_advceComApplTpCd_onclick
 * @description rd_advceComApplTpCd 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_advceComApplTpCd_onclick = function(e){
    try {
        scwin.disabled('__self.value')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25720.rd_advceComApplTpCd_onclick' }); }
};

/**
 * @method
 * @name btn_findCompany_onclick
 * @description btn_findCompany 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_findCompany_onclick = async function(e){
    try {
        await scwin.findCompany()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25720.btn_findCompany_onclick' }); }
};

/**
 * @method
 * @name btn_modify_onclick
 * @description 「수정」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_modify_onclick = async function(e){
    try {
        await scwin.modify()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25720.btn_modify_onclick' }); }
};

/**
 * @method
 * @name btn_application_onclick
 * @description 「신청」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_application_onclick = async function(e){
    try {
        await scwin.application()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25720.btn_application_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_application
 * @description application 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_application = async function () {
    const sbmOptions = {
        id: "tx_fn_application",
        method: "post",
        action: "/account/advceComInfo.do",
        ref: "dma_applicationReq",
        target: "dlt_advceComApplList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_modify
 * @description modify 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_modify = async function () {
    const sbmOptions = {
        id: "tx_fn_modify",
        method: "post",
        action: "/account/advceComInfo.do",
        ref: "dma_modifyReq",
        target: "dlt_advceComApplList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_existYn_xhr
 * @description exist Yn xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_existYn_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_existYn_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_existYn_xhr", unresolved: "action:self_submit:tx_fn_existYn_xhr" };
};

/**
 * @method
 * @name existYn
 * @description exist Yn 처리
 * @param {String} comNm comNm
 * @param {String} advceComIsurCd advceComIsurCd
 * @param {String} advceComApplTpCd advceComApplTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.existYn = async function (comNm, advceComIsurCd, advceComApplTpCd) {
    advceComApplTpCd = advceComApplTpCd;
    (document.searchForm || { elements: [] }).action = "/account/advceComInfo.do";
    $c.util.getComponent('dma_applicationReq').set('method', "chkAdvceCom");
    $c.util.getComponent("dma_applicationReq").set("advceComIsurCd", advceComIsurCd);
    $c.util.getComponent("dma_applicationReq").set("advceComApplTpCd", advceComApplTpCd);
    let result = await scwin.tx_fn_existYn_xhr();
    result = scwin.trim(result);
    let processYn = false;
    let msg = "";
    if (result === "addAppl") {
        msg = "『" + comNm + "』코넥스 법인은  이미 [추가] 신청하셨습니다.";
    } else {
        if (result === "addOk") {
            msg = "『" + comNm + "』코넥스 법인을 자문기업으로 [추가] 신청하시겠습니까?";
        } else {
            if (result === "addNot") {
                msg = "[추가] 신청하신 『" + comNm + "』코넥스 법인은 현재 자문기업으로 등록되어 있습니다.";
            } else {
                if (result === "exceptAppl") {
                    msg = "『" + comNm + "』코넥스 법인은  이미 [제외] 신청하셨습니다.";
                } else {
                    if (result === "exceptOk") {
                        msg = "『" + comNm + "』코넥스 법인을 자문기업에서 [제외] 신청하시겠습니까?";
                    } else {
                        if (result === "exceptNot") {
                            msg = "[제외] 신청하신 『" + comNm + "』코넥스 법인은 현재 등록된 자문기업이 아닙니다.";
                        }
                    }
                }
            }
        }
    }
    if (result === "addOk" || result === "exceptOk") {
        if (await $c.win.confirm(msg)) {
            processYn = true;
        }
    } else {
        await $c.win.alert(msg);
    }
    return processYn;
};

/**
 * @method
 * @name disabled
 * @description disabled 처리
 * @param {String} advceComApplTpCd advceComApplTpCd
 * @returns {void}
 * @hidden N
 */
scwin.disabled = function (advceComApplTpCd) {
    if (advceComApplTpCd === 'A') {
        $c.util.getComponent('cal_contrtDd').setStyle("background-color", "#FFFFFF");
        $c.util.getComponent("cal_releasDd").setValue("");
        $c.util.getComponent('cal_releasDd').setStyle("background-color", "#F1F1F1");
    } else {
        if (advceComApplTpCd === 'E') {
            $c.util.getComponent('cal_releasDd').setStyle("background-color", "#FFFFFF");
            $c.util.getComponent("cal_contrtDd").setValue("");
            $c.util.getComponent('cal_contrtDd').setStyle("background-color", "#F1F1F1");
        }
    }
};

/**
 * @method
 * @name application
 * @description application 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.application = async function () {
    // TODO Stage2(규칙19): fieldEl(DOM 요소 계약) → 컴포넌트 getValue/setValue 계약으로 전환 필요
    const frm = (document.advceComApplInfoForm || { elements: [] });
    const comNm = $c.util.getComponent('ipt_comNm').getValue();
    const advceComIsurCd = $c.util.getComponent("dma_applicationReq").get("advceComIsurCd");
    let advceComApplTpCd = "";
    advceComApplTpCd = $c.util.getComponent("dma_applicationReq").get("advceComApplTpCd");
    if (!scwin.isChecked(frm.advceComApplTpCd)) {
        await $c.win.alert('신청구분을 선택하세요.');
        return;
    }
    if (await scwin.nullChk($c.util.fieldEl('cal_applReqDd', 'applReqDd'))) {
        return;
    }
    if (!await scwin.chkToday($c.util.fieldEl('cal_applReqDd', 'applReqDd'))) {
        return;
    }
    if (advceComApplTpCd === 'A') {
        if (await scwin.nullChk($c.util.fieldEl('cal_contrtDd', 'contrtDd'))) {
            return;
        }
        if (scwin.isNotNull($c.util.fieldEl('cal_releasDd', 'releasDd'))) {
            await $c.win.alert('[추가] 신청시에는 해제일을 입력하지 않습니다.');
            $c.util.getComponent("cal_releasDd").setValue("");
            return;
        }
    } else {
        if (advceComApplTpCd === 'E') {
            if (await scwin.nullChk($c.util.fieldEl('cal_releasDd', 'releasDd'))) {
                return;
            }
            if (!await scwin.chkToday($c.util.fieldEl('cal_releasDd', 'releasDd'))) {
                return;
            }
            if (scwin.isNotNull($c.util.fieldEl('cal_contrtDd', 'contrtDd'))) {
                await $c.win.alert('[제외] 신청시에는 계약일을 입력하지 않습니다.');
                $c.util.getComponent("cal_contrtDd").setValue("");
                return;
            }
        }
    }
    if (await scwin.nullChk($c.util.fieldEl('ipt_comNm', 'comNm'))) {
        return;
    }
    if (await scwin.existYn(comNm, advceComIsurCd, advceComApplTpCd)) {
        $c.util.getComponent('dma_applicationReq').set('method', "advceComInfoApply");
        const nr = await scwin.tx_fn_application();
        if (nr && nr.responseJSON && nr.responseJSON.success === true) {
            $c.win.moveUrl("/ui/jsp/JLDFIL25710.xml", { "method": "advceComInfoApply" });
        }
    }
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function () {
    const statVal = $c.util.getComponent("dma_applicationReq").get("advceComProcsStatNm");
    if (statVal === "미처리") {
        $c.util.getComponent('dma_applicationReq').set('method', "advceComInfoApply");
        $c.util.getComponent('dma_applicationReq').set('modifyYn', "Y");
        const nr = await scwin.tx_fn_modify();
        if (nr && nr.responseJSON && nr.responseJSON.success === true) {
            $c.win.moveUrl("/ui/jsp/JLDFIL25710.xml", { "method": "advceComInfoApply", "modifyYn": "Y" });
        }
    } else {
        await $c.win.alert("[미처리] 상태인 신청건만 수정이 가능합니다.");
    }
};

/**
 * @method
 * @name findCompany
 * @description find Company 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findCompany = async function () {
    const corpSearchURL = '/ui/jsp/JLDFIL00033.xml';
    scwin.setCorpInfo_recv(await $c.win.openPopup(corpSearchURL, { id: "corpWin", scrollbars: false, resizable: false, width: "600", height: "570", type: "pageFramePopup" }, { method: "loadInitPage", marketType: "konexMkt" }));
};

/**
 * @method
 * @name loadForm
 * @description load Form 처리
 * @param {*} seq seq
 * @param {String} advceComIsurCd advceComIsurCd
 * @param {String} comNm comNm
 * @param {String} advceComApplTpCd advceComApplTpCd
 * @param {String} applReqDd applReqDd
 * @param {String} contrtDd contrtDd
 * @param {String} releasDd releasDd
 * @param {String} advceComProcsStatNm advceComProcsStatNm
 * @returns {void}
 * @hidden N
 */
scwin.loadForm = function (seq, advceComIsurCd, comNm, advceComApplTpCd, applReqDd, contrtDd, releasDd, advceComProcsStatNm) {
    const form = (document.advceComApplInfoForm || { elements: [] });
    const regexp = /-/g;
    const undashApplReqDd = applReqDd.replace(regexp, "");
    const undashContrtDd = contrtDd.replace(regexp, "");
    const undashReleasDd = releasDd.replace(regexp, "");
    const obj = form.advceComApplTpCd;
    $c.util.getComponent("dma_applicationReq").set("seq", seq);
    $c.util.getComponent("dma_applicationReq").set("advceComIsurCd", advceComIsurCd);
    $c.util.getComponent('ipt_comNm').setValue(comNm);
    for (let i = 0; i < obj.length; i++) {
        if (obj[i].value === advceComApplTpCd) {
            obj[i].checked = true;
        }
    }
    scwin.disabled(advceComApplTpCd);
    $c.util.getComponent('cal_applReqDd').setValue(undashApplReqDd);
    $c.util.getComponent('cal_contrtDd').setValue(undashContrtDd);
    $c.util.getComponent('cal_releasDd').setValue(undashReleasDd);
    $c.util.getComponent("dma_applicationReq").set("advceComProcsStatNm", advceComProcsStatNm);
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    $c.util.getComponent("dma_applicationReq").set("advceComIsurCd", isurCd);
    $c.util.getComponent("ipt_comNm").setValue(comAbbrv);
};

/**
 * @method
 * @name trim
 * @description trim 처리
 * @param {*} _str _str
 * @returns {void}
 * @hidden N
 */
scwin.trim = function (_str) {

    if(typeof(_str)!=='undefined') return _str.replace(/^\s{1,}/, "").replace(/\s{1,}$/, "");
    else return _str;
};

/**
 * @method
 * @name isChecked
 * @description is Checked 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.isChecked = function (_obj) {

    let isChecked = false;
    for(let i=0; i<_obj.length; i++){
        if(_obj[i].checked){
            isChecked = true;
            break;
        }
    }
    return isChecked;
};

/**
 * @method
 * @name nullChk
 * @description null Chk 처리
 * @param {*} _obj _obj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.nullChk = async function (_obj) {

    // ie11에서 alt값을 'undefined'로 인식하므로 수정
    if(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj) === ''  || typeof ((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj) === 'undefined') {
        return await scwin.isNull(_obj, _obj.title);
    }

    return await scwin.isNull(_obj, ((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj));
};

/**
 * @method
 * @name chkToday
 * @description chk Today 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkToday = async function (obj) {

    const today = new Date();

    const nowYear  = today.getYear();
    let nowMonth  = today.getMonth() + 1;
    let nowDate  = today.getDate();

    if(nowMonth < 10) {
        nowMonth = "0" + nowMonth;
    }
    if(parseInt(nowDate) < 10) {
        nowDate = "0" + nowDate;
    }

    const toDd  = nowYear + '' + nowMonth + '' + nowDate;

    if(parseInt(toDd) >= parseInt(obj.value)) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(obj) + " : 오늘 이후의 일자를 입력하세요.");
        return false;
    }
    return true;

};

/**
 * @method
 * @name isNotNull
 * @description is Not Null 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.isNotNull = function (_obj) {

    if(scwin.trim(_obj.value) === ''){
        return false;
    }
    return true;
};

/**
 * @method
 * @name isNull
 * @description is Null 처리
 * @param {*} _obj _obj
 * @param {*} _msg _msg
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isNull = async function (_obj, _msg) {

